mod setup{use std::{path::PathBuf,sync::OnceLock};pub fn dir()->PathBuf{std::env::var_os("HEC_SETUP_DIR").map(PathBuf::from).expect("mandatory setup directory")}
 fn array<const N:usize>(name:&str)->[u64;N]{std::fs::read_to_string(dir().join(name)).unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect::<Vec<_>>().try_into().unwrap()}
 pub fn hc()->[u64;8]{static H:OnceLock<[u64;8]>=OnceLock::new();*H.get_or_init(||array("HC.txt"))}pub fn qf()->[u64;15]{static Q:OnceLock<[u64;15]>=OnceLock::new();*Q.get_or_init(||array("QF.txt"))}pub fn verify_model(){assert_eq!(qf()[0],1);assert!(crate::target::is_smooth(&qf(),631));}}
#[allow(dead_code)]mod target{include!("../hec_alignment13_20261115/atlas/target.rs");include!("target_api631.rs");}
#[allow(dead_code)]mod source{
 mod arith { include!("../hec_kernel631_20261115/arith.rs"); }
 use arith::{base,Curve,Div,Field,Pol,E,O,P,Z};use hec_native_ic::{fp::Fp,jac,poly::Poly};use std::{fs,collections::HashMap};
 include!("../hec_normalize631_20261115/functions.rs");include!("../hec_normalize631_20261115/loader.rs");include!("../hec_geometry13_20261115/jets.rs");include!("../hec_geometry631_20261115/coordinates.rs");include!("source_api.rs");include!("source_jet.rs");include!("fiber_select.rs");
 fn local_torsion(c:&jac::Curve)->jac::Div{for(x,y)in hec_native_ic::instance::factor_base(c).into_iter().take(16){let mut t=c.mul(&c.place(x,y),59296481);if c.is_zero(&t){continue;}let mut depth=0;while !c.is_zero(&c.mul(&t,2)){t=c.mul(&t,2);depth+=1;assert!(depth<=2);}assert_eq!(t.u.deg(),3);assert_eq!(t.v,Poly::zero());println!("LOCAL_2TORSION projection_depth={depth}");return t;}panic!("no_local_2torsion");}
 pub fn run(out:&std::path::Path){let(src,base,pair)=calibrate();let pts=crate::target::rational_points(&super::setup::qf(),P);assert_eq!(pts.len(),597);assert!(pair.iter().all(|p|pts.contains(p)));let j=crate::target::QuarticJacobian::with_points(P,super::setup::qf(),pts).unwrap();let image=crate::target::scalar(&j,crate::target::difference(&j,pair[0],pair[1]),4);assert_ne!(image,j.zero());assert_eq!(crate::target::scalar(&j,image,59296481),j.zero());assert!(!src.refc.is_zero(&base)&&src.refc.is_zero(&src.refc.mul(&base,59296481)));let mut v=vec![];for p in[base.u,base.v]{v.push(p.n as u64);v.extend_from_slice(&p.c[..p.n]);}for p in pair{v.extend(p);}fs::write(out.join("CALIBRATION.txt"),v.iter().map(u64::to_string).collect::<Vec<_>>().join(" ")+"\n").unwrap();println!("PASS F631_calibration_candidate=true clearing_multiplier=4 source_and_target_nonzero_prime_subgroups=true actual_global_transfer_or_alignment_verified=false");}
}